 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # A complete horizontal bar identifies the color whose partial bar is
    # extended; recolor the background portion after its prefix with 1.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    full_colors = {row[0] for row in grid if row and all(v == row[0] for v in row)}
    for row in out:
        if row and row[0] in full_colors:
            k = 0
            while k < len(row) and row[k] == row[0]:
                k += 1
            if 0 < k < len(row) and all(v == background for v in row[k:]):
                row[k:] = [1] * (len(row) - k)
    return out
